                _ringRecordStartTime = Date.now();
                showRingRecording(true);
                updateRingRecordTimer();
                _ringRecordTimer = setInterval(updateRingRecordTimer, 200);
                if (ringtoneStatus) ringtoneStatus.textContent = '';
