    // Delete account
    // Clear all client-side data (localStorage, sessionStorage, non-HttpOnly cookies).
    // HttpOnly cookies can only be cleared by the server (see /api/logout GET).
    function clearAllClientData() {
        // Preserve the session-duration preference (Settings → Security): a
        // benign browser preference (a plain number, never keys or identity
        // data) that users shouldn't have to re-enter on every login. All
        // logins, keys, caches, and other settings are fully cleared. Using
        // the iterate-and-skip pattern (like the login-page wipe in auth.js)
        // avoids localStorage.clear()+re-set reordering keys or throwing on
        // a full quota.
        var keepDurationKeys = { 'session_duration_seconds': 1, 'reauth_duration_seconds': 1 };
        var allKeys = [];
        for (var di = 0; di < localStorage.length; di++) {
            var dk = localStorage.key(di);
            if (dk) allKeys.push(dk);
        }
        for (var dj = 0; dj < allKeys.length; dj++) {
            if (keepDurationKeys[allKeys[dj]]) continue;
            try { Storage.prototype.removeItem.call(localStorage, allKeys[dj]); } catch (_) {}
        }
        try { sessionStorage.clear(); } catch (_) {}
        document.cookie.split(';').forEach(function(c) {
            document.cookie = c.replace(/^ +/, '').replace(/=.*/, '=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/');
        });
        // The ringtone + notification-sound audio lives in IndexedDB
        // (localStorage quota is too small for audio) — wipe it too, otherwise
        // "Clear All Data" leaves the previous account's audio behind.
        try { indexedDB.deleteDatabase('e2e_notif_sound'); } catch (_) {}
    }

    // Call the server-side logout endpoint to clear the HttpOnly cookie
    async function serverLogout() {
        try {
            await fetch('/api/logout', { method: 'POST', headers: { 'Authorization': 'Bearer ' + token() } });
        } catch (_) {}
    }

    // Delete Account — password-gated, like every other permanent action
    // (2FA, password change, kill switch): a stolen session can't delete the
    // account without the real password.
    var deleteAcctBtn = document.getElementById('delete-account-btn');
    var deleteAcctSection = document.getElementById('delete-account-section');
    var deleteAcctStatus = document.getElementById('delete-account-status');
    function setDeleteAcctStatus(msg, kind) {
        if (!deleteAcctStatus) return;
        deleteAcctStatus.textContent = msg;
        deleteAcctStatus.style.color = kind === 'error' ? 'var(--danger)' : (kind === 'success' ? '#43b581' : 'var(--text-muted)');
    }
    function resetDeleteAcctInputs() {
        var inp = document.getElementById('delete-account-password');
        if (inp) { inp.type = 'password'; inp.value = ''; }
        var tgl = document.getElementById('toggle-delete-account-password');
        if (tgl) { tgl.innerHTML = '&#128065;'; tgl.classList.remove('active'); }
    }
    if (deleteAcctBtn && deleteAcctSection) {
        deleteAcctBtn.addEventListener('click', function () {
            var open = deleteAcctSection.style.display !== 'block';
            deleteAcctSection.style.display = open ? 'block' : 'none';
            if (open) { resetDeleteAcctInputs(); setDeleteAcctStatus('', ''); }
        });
        document.getElementById('delete-account-cancel-btn').addEventListener('click', function () {
            deleteAcctSection.style.display = 'none';
            resetDeleteAcctInputs();
            setDeleteAcctStatus('', '');
        });
        document.getElementById('toggle-delete-account-password').addEventListener('click', function () {
            var inp = document.getElementById('delete-account-password');
            if (!inp) return;
            var visible = inp.type === 'text';
            inp.type = visible ? 'password' : 'text';
            this.innerHTML = visible ? '&#128065;' : '&#128064;';
            this.classList.toggle('active', !visible);
        });
        document.getElementById('delete-account-confirm-btn').addEventListener('click', async function () {
            var pw = document.getElementById('delete-account-password').value;
            if (!pw) { setDeleteAcctStatus('Enter your password to delete the account', 'error'); return; }
            if (!confirm('Are you sure you want to delete your account? This cannot be undone.')) return;
            if (!confirm('Really? All your messages, servers, files, and keys will be permanently lost.')) return;
            setDeleteAcctStatus('Deleting account…', '');
            try {
                const current_password = await computeHashedPasswordGlobal(pw);
                const res = await authFetch('/api/me', {
                    method: 'DELETE',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ current_password })
                });
                if (res.ok) {
                    clearAllClientData();
                    if (ws) ws.close();
                    // The server clears the HttpOnly cookie in the delete_me response,
                    // so we can redirect directly to login without the /api/logout roundtrip.
                    window.location.href = '/login.html';
                    return;
                }
                const err = await res.json();
                setDeleteAcctStatus(err.error || 'Failed to delete account', 'error');
            } catch (e) {
                setDeleteAcctStatus('Server is not running', 'error');
            }
        });
    }

    // Logout is handled in settings (Clear All Data / Sign Out)

    // Clear all data button in settings — robust logout + wipe sequence
    document.getElementById('clear-all-data-btn').addEventListener('click', async () => {
        if (!confirm('This will clear ALL local data (logins, keys, settings) and sign you out. The session-duration setting (Settings → Security) is kept. Continue?')) return;
        // 1. Close websocket first so no more messages arrive
        if (ws) { try { ws.close(); } catch (_) {} ws = null; }
        // 2. Call server logout to clear HttpOnly cookie (while token is still present)
        await serverLogout();
        // 3. Clear all client-side data
        clearAllClientData();
        // 4. Redirect directly to login page since the server already cleared the cookie
        window.location.href = '/login.html';
    });

    // Security tab - session countdown
    function updateSessionCountdown() {
        const countdownEl = document.getElementById('session-countdown');
        if (!countdownEl) return;
        const expiresAt = getTokenExpiresAt(token());
        if (!expiresAt) { countdownEl.textContent = 'Unknown'; return; }
        // Also keep the "expires at" line in the security log in sync
        const expiresAtEl = document.getElementById('session-expires-at');
        if (expiresAtEl) expiresAtEl.textContent = fmtDateTime(expiresAt);
        const msLeft = expiresAt - Date.now();
        if (msLeft <= 0) { countdownEl.textContent = 'Expired'; return; }
        const days = Math.floor(msLeft / 86400000);
        const hours = Math.floor((msLeft % 86400000) / 3600000);
        const minutes = Math.floor((msLeft % 3600000) / 60000);
        countdownEl.textContent = days + 'd ' + hours + 'h ' + minutes + 'm';
    }
    updateSessionCountdown();
    setInterval(updateSessionCountdown, 60000);

    // Heartbeat interval selector + checkbox toggles (security tab)
    var heartbeatSelect = document.getElementById('heartbeat-interval-select');
    if (heartbeatSelect) {
        var savedInterval = localStorage.getItem('key_heartbeat_interval') || '0';
        heartbeatSelect.value = savedInterval;
        heartbeatSelect.addEventListener('change', function() {
            localStorage.setItem('key_heartbeat_interval', this.value);
            if (ws && ws.readyState === WebSocket.OPEN) {
                restartRefreshHeartbeat();
            }
        });
    }
    // Session duration selector (security tab) — how long the session should
    // last after login, registration, AND re-authentication. Defaults to 30 days.
    // Max 30 days (server clamps again). Stored under session_duration_seconds
    // (legacy key reauth_duration_seconds still read as a fallback).
    var reauthDurationSelect = document.getElementById('reauth-duration-select');
    if (reauthDurationSelect) {
        var _validDurations = ['3600', '21600', '43200', '86400', '259200', '604800', '1209600', '2592000'];
        var savedDur = localStorage.getItem('session_duration_seconds');
        if (savedDur === null) savedDur = localStorage.getItem('reauth_duration_seconds');
        if (_validDurations.indexOf(savedDur) === -1) savedDur = '2592000';
        reauthDurationSelect.value = savedDur;
        reauthDurationSelect.addEventListener('change', function() {
            localStorage.setItem('session_duration_seconds', this.value);
            localStorage.setItem('reauth_duration_seconds', this.value); // legacy read path
        });
    }
    // Wire refresh-action checkboxes. Two groups with matching semantics to
    // refreshAll(): the default-on group runs unless explicitly toggled off
    // (!== 'false'), the opt-in group only runs once the user enables it
    // (=== 'true'). The checkbox state mirrors the ACTUAL runtime behavior.
    var refreshCheckboxes = ['hb_refresh_keys', 'hb_refresh_profiles', 'hb_refresh_members', 'hb_refresh_messages'];
    refreshCheckboxes.forEach(function(id) {
        var cb = document.getElementById(id);
        if (!cb) return;
        var saved = localStorage.getItem(id);
        cb.checked = saved !== 'false';
        cb.addEventListener('change', function() {
            localStorage.setItem(id, this.checked ? 'true' : 'false');
        });
    });
    // Opt-in heartbeat actions: heavier refreshes that rebuild DOM sections
    // (DM sidebar, server strip) or hit extra endpoints. Disabled until the
    // user explicitly enables them.
    var optInRefreshCheckboxes = ['hb_refresh_dms', 'hb_refresh_servers', 'hb_refresh_friend_requests', 'hb_refresh_presence', 'hb_refresh_voice', 'hb_refresh_channels'];
    optInRefreshCheckboxes.forEach(function(id) {
        var cb = document.getElementById(id);
        if (!cb) return;
        var saved = localStorage.getItem(id);
        cb.checked = saved === 'true';
        cb.addEventListener('change', function() {
            localStorage.setItem(id, this.checked ? 'true' : 'false');
        });
    });

    // Re-auth button
    const reauthBtn = document.getElementById('reauth-btn');
    const reauthSection = document.getElementById('reauth-section');
    const reauthConfirmBtn = document.getElementById('reauth-confirm-btn');
    const reauthError = document.getElementById('reauth-error');

    // Devices panel: kick-all button + per-device kick buttons (delegated so
    // freshly rendered rows work without re-binding).
    var kickAllBtn = document.getElementById('kick-all-devices-btn');
    if (kickAllBtn) kickAllBtn.addEventListener('click', kickAllDevices);
    var kickAllYes = document.getElementById('kick-all-confirm-yes');
    if (kickAllYes) kickAllYes.addEventListener('click', confirmKickAllDevices);
    var kickAllCancel = document.getElementById('kick-all-confirm-cancel');
    if (kickAllCancel) kickAllCancel.addEventListener('click', function () { hideModal('kick-all-confirm-modal'); });
    var kickAllToggle = document.getElementById('toggle-kick-all-password');
    if (kickAllToggle) {
        kickAllToggle.addEventListener('click', function () {
            var inp = document.getElementById('kick-all-password');
            if (!inp) return;
            var visible = inp.type === 'text';
            inp.type = visible ? 'password' : 'text';
            kickAllToggle.innerHTML = visible ? '&#128065;' : '&#128064;';
            kickAllToggle.classList.toggle('active', !visible);
        });
    }
    var devicesList = document.getElementById('devices-list');
    if (devicesList) {
        devicesList.addEventListener('click', function (e) {
            var btn = e.target.closest ? e.target.closest('.device-kick-btn') : null;
            if (btn && btn.dataset.sid) kickDevice(btn.dataset.sid);
        });
    }

    if (reauthBtn) {
        reauthBtn.addEventListener('click', () => {
            reauthSection.style.display = reauthSection.style.display === 'none' ? 'block' : 'none';
            reauthError.style.display = 'none';
            // Always reset password input to hidden state when opening
            if (reauthPasswordInput) {
                reauthPasswordInput.type = 'password';
                reauthPasswordInput.value = '';
            }
            if (reauthToggleBtn) {
                reauthToggleBtn.innerHTML = '&#128065;';
                reauthToggleBtn.classList.remove('active');
            }
        });
    }

    // Re-auth password show/hide toggle
    var reauthToggleBtn = document.getElementById('toggle-reauth-password');
    var reauthPasswordInput = document.getElementById('reauth-password');
    if (reauthToggleBtn && reauthPasswordInput) {
        reauthToggleBtn.addEventListener('click', function () {
            const visible = reauthPasswordInput.type === 'text';
            reauthPasswordInput.type = visible ? 'password' : 'text';
            reauthToggleBtn.innerHTML = visible ? '&#128065;' : '&#128064;';
            reauthToggleBtn.classList.toggle('active', !visible);
        });
    }

    if (reauthConfirmBtn) {
        reauthConfirmBtn.addEventListener('click', async () => {
            const password = document.getElementById('reauth-password').value;
            if (!password) { reauthError.textContent = 'Enter your password'; reauthError.style.display = 'block'; return; }
            try {
                // Hash password client-side (HMAC-SHA256) if auth key is available
                var sendPassword;
                try {
                    sendPassword = await computeHashedPasswordGlobal(password);
                } catch (_) {
                    sendPassword = password; // Fall back to raw password for legacy accounts
                }
                // Custom session duration chosen in settings (clamped 1min–30 days;
                // the server clamps again defensively).
                var durationSecs = getSessionDurationSecs();
                var devId = localStorage.getItem('e2e_device_key');
                const res = await fetch('/api/reauth', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': 'Bearer ' + token()
                    },
                    body: JSON.stringify({ password: sendPassword, duration_seconds: durationSecs, device_id: devId || undefined, device_name: getDeviceName() })
                });
                const data = await res.json();
                if (!res.ok) {
                    reauthError.textContent = data.error || 'Re-authentication failed';
                    reauthError.style.display = 'block';
                    return;
                }
                // Capture the OLD expiry before swapping in the new token, so the
                // security log can show "from → to".
                var oldExpAt = getTokenExpiresAt(token());
                localStorage.setItem('token', data.token);
                localStorage.setItem('user', JSON.stringify(data.user));
                reauthSection.style.display = 'none';
                document.getElementById('reauth-password').value = '';
                updateSessionCountdown();
                // Re-arm the auto-logout timer against the NEW token's expiry
                // (reschedule-safe — clears any timer armed for the old token).
                checkTokenExpiry();
                // Log the re-auth event (from-expiry → to-expiry + chosen duration)
                // and refresh the on-screen security log.
                recordReauthEvent(oldExpAt, getTokenExpiresAt(data.token), durationSecs);
                renderSessionLog();
                alert('Session extended by ' + fmtDuration(durationSecs));
            } catch (e) {
                reauthError.textContent = 'Server is not running';
                reauthError.style.display = 'block';
            }
        });
    }

    // --- Change password (Settings → Security) ---
    var changePwBtn = document.getElementById('change-pw-btn');
    var changePwSection = document.getElementById('password-change-section');
    var changePwStatus = document.getElementById('change-pw-status');
    var changePwConfirmBtn = document.getElementById('change-pw-confirm-btn');
    // Pending { cur, nw } awaiting the confirmation modal's "Yes" — cleared on
    // cancel or once the change is submitted.
    var _pendingChangePw = null;

    function resetChangePwInputs() {
        ['change-pw-current', 'change-pw-new', 'change-pw-confirm'].forEach(function (id) {
            var inp = document.getElementById(id);
            if (inp) { inp.type = 'password'; inp.value = ''; }
            var tgl = document.getElementById('toggle-' + id);
            if (tgl) { tgl.innerHTML = '&#128065;'; tgl.classList.remove('active'); }
        });
    }
    function setChangePwStatus(msg, kind) {
        if (!changePwStatus) return;
        changePwStatus.textContent = msg;
        changePwStatus.style.color = kind === 'error' ? 'var(--danger)' : (kind === 'success' ? '#43b581' : 'var(--text-muted)');
    }

    if (changePwBtn) {
        changePwBtn.addEventListener('click', function () {
            var open = changePwSection.style.display !== 'block';
            changePwSection.style.display = open ? 'block' : 'none';
            if (open) { resetChangePwInputs(); setChangePwStatus('', ''); }
        });
    }
    ['toggle-change-pw-current', 'toggle-change-pw-new', 'toggle-change-pw-confirm'].forEach(function (tid) {
        var tgl = document.getElementById(tid);
        if (!tgl) return;
        tgl.addEventListener('click', function () {
            var inp = document.getElementById(tid.replace('toggle-', ''));
            if (!inp) return;
            var visible = inp.type === 'text';
            inp.type = visible ? 'password' : 'text';
            tgl.innerHTML = visible ? '&#128065;' : '&#128064;';
            tgl.classList.toggle('active', !visible);
        });
    });

    // Core change flow: the raw password is the master key, so the client
    // re-wraps every password-encrypted blob (hash_key, identity escrow,
    // friend code, key blob) with the NEW password. The keys themselves never
    // change, so nothing else is affected.
    async function performPasswordChange(oldPw, newPw) {
        var currentUser = null;
        try { currentUser = JSON.parse(localStorage.getItem('user') || 'null'); } catch (_) {}
        if (!currentUser || !currentUser.username || !currentUser.id) throw new Error('Not signed in');
        // 1. Fetch the password-wrapped hash_key and decrypt it with the old
        //    password — this doubles as the "is the current password right?" check.
        var paramsRes = await fetch('/api/auth-params/' + encodeURIComponent(currentUser.username));
        if (!paramsRes.ok) throw new Error('Could not load account credentials');
        var params = await paramsRes.json();
        if (!params.encrypted_hash_key || !params.hash_key_salt || !params.hash_key_nonce) throw new Error('Account credentials unavailable on server');
        var hashKeyB64 = E2ECrypto.decryptWithPassword(params.encrypted_hash_key, oldPw, params.hash_key_salt, params.hash_key_nonce);
        if (!hashKeyB64) throw new Error('Current password is incorrect');
        var hashKeyBytes = new Uint8Array(E2ECrypto.base64ToArrayBuffer(hashKeyB64));

        // 2. Same hash_key → hashes for old (verify) and new (store) password.
        var payload = {
            old_password: E2ECrypto.hmacHex(hashKeyBytes, oldPw),
            new_password: E2ECrypto.hmacHex(hashKeyBytes, newPw)
        };

        // 3. Re-encrypt everything with the NEW password.
        var encHashKey = E2ECrypto.encryptWithPassword(hashKeyB64, newPw);
        payload.encrypted_hash_key = encHashKey.encrypted_private_key;
        payload.hash_key_salt = encHashKey.salt;
        payload.hash_key_nonce = encHashKey.nonce;
        // Identity key escrow (best effort — only if the local key is present).
        var idPrivB64 = localStorage.getItem('e2e_identity_private_' + currentUser.id);
        if (idPrivB64) {
            var esc = E2ECrypto.encryptWithPassword(idPrivB64, newPw);
            payload.encrypted_identity_priv = esc.encrypted_private_key;
            payload.escrow_salt = esc.salt;
            payload.escrow_nonce = esc.nonce;
        }
        // Friend code (best effort).
        var fc = localStorage.getItem('e2e_friend_code');
        if (fc) {
            var fcEnc = E2ECrypto.encryptWithPassword(fc, newPw);
            payload.encrypted_friend_code = fcEnc.encrypted_private_key;
            payload.friend_code_salt = fcEnc.salt;
            payload.friend_code_nonce = fcEnc.nonce;
        }
        // Key blob (identity + message keys) — sent in the SAME request so the
        // server can never end up with a blob encrypted by a different password.
        if (typeof E2ECrypto.buildKeyBundle === 'function' && typeof E2ECrypto.encryptKeyBundle === 'function') {
            var blob = E2ECrypto.encryptKeyBundle(E2ECrypto.buildKeyBundle(), newPw);
            payload.encrypted_blob = blob.encrypted_private_key;
            payload.blob_salt = blob.salt;
            payload.blob_nonce = blob.nonce;
        }

        // 4. Submit — the server verifies the old hash (constant-time) and
        //    swaps every blob in one go.
        var res = await authFetch('/api/password/change', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        var data = await res.json();
        if (!res.ok) throw new Error(data.error || 'Password change failed');

        // 5. Local housekeeping — swap the stored password and re-key the
        //    at-rest secure storage to the new password-derived key, so this
        //    device keeps auto-hashing with the new password.
        try {
            if (window._secRekeyToPassword) {
                window._secRekeyToPassword(newPw);
            } else {
                var devKey = localStorage.getItem('e2e_device_key');
                if (devKey) {
                    var dk = new Uint8Array(E2ECrypto.base64ToArrayBuffer(devKey));
                    localStorage.setItem('e2e_encrypted_password', E2ECrypto.encodeEncryptedFileKey(btoa(newPw), dk));
                }
            }
        } catch (_) {}
    }

    if (changePwConfirmBtn) {
        changePwConfirmBtn.addEventListener('click', function () {
            var cur = document.getElementById('change-pw-current').value;
            var nw = document.getElementById('change-pw-new').value;
            var cf = document.getElementById('change-pw-confirm').value;
            if (!cur || !nw || !cf) { setChangePwStatus('Fill in all three fields.', 'error'); return; }
            if (nw !== cf) { setChangePwStatus('New passwords do not match.', 'error'); return; }
            if (nw.length < 8) { setChangePwStatus('New password must be at least 8 characters.', 'error'); return; }
            // Validation passed — ask for confirmation before doing anything:
            // a password change signs out every other device, so it must never
            // fire on a single stray click. The actual change runs only when
            // the user confirms in the modal.
            _pendingChangePw = { cur: cur, nw: nw };
            showModal('change-pw-confirm-modal');
        });
    }
    var changePwConfirmYes = document.getElementById('change-pw-confirm-yes');
    var changePwConfirmCancel = document.getElementById('change-pw-confirm-cancel');
    if (changePwConfirmYes) {
        changePwConfirmYes.addEventListener('click', async function () {
            var pending = _pendingChangePw;
            if (!pending) return;
            _pendingChangePw = null;
            var btn = this;
            btn.disabled = true;
            setChangePwStatus('Changing password…', '');
            try {
                await performPasswordChange(pending.cur, pending.nw);
                hideModal('change-pw-confirm-modal');
                resetChangePwInputs();
                changePwSection.style.display = 'none';
                setChangePwStatus('✅ Password changed. All other devices were signed out and will need the new password to sign in again.', 'success');
            } catch (e) {
                hideModal('change-pw-confirm-modal');
                setChangePwStatus(e.message || 'Failed to change password.', 'error');
            }
            btn.disabled = false;
        });
    }
    if (changePwConfirmCancel) {
        changePwConfirmCancel.addEventListener('click', function () {
            _pendingChangePw = null;
            hideModal('change-pw-confirm-modal');
        });
    }

    // --- Save Backup Now (Settings → Security) ---
    var saveBackupNowBtn = document.getElementById('save-backup-now-btn');
    var saveBackupStatus = document.getElementById('save-backup-status');
    if (saveBackupNowBtn) {
        saveBackupNowBtn.addEventListener('click', async function () {
            saveBackupNowBtn.disabled = true;
            saveBackupNowBtn.innerHTML = '⏳ Saving...';
            if (saveBackupStatus) { saveBackupStatus.textContent = 'Encrypting keys...'; saveBackupStatus.style.color = 'var(--text-muted)'; }
            try {
                var encPw = localStorage.getItem('e2e_encrypted_password');
                var devKeyStr = localStorage.getItem('e2e_device_key');
                if (!encPw || !devKeyStr) throw new Error('Not logged in');
                var dk = new Uint8Array(E2ECrypto.base64ToArrayBuffer(devKeyStr));
                var pwB64 = E2ECrypto.decodeEncryptedFileKey(encPw, dk);
                if (!pwB64) throw new Error('Could not decode password');
                var pw = atob(pwB64);
                var t = localStorage.getItem('token');
                if (!t) throw new Error('No auth token');
                var bundle = E2ECrypto.buildKeyBundle();
                var enc = E2ECrypto.encryptKeyBundle(bundle, pw);
                if (saveBackupStatus) saveBackupStatus.textContent = 'Uploading to server...';
                var res = await fetch('/api/key-blob', {
                    method: 'PUT',
                    headers: { 'Authorization': 'Bearer ' + t, 'Content-Type': 'application/json' },
                    body: JSON.stringify({ encrypted_blob: enc.encrypted_private_key, salt: enc.salt, nonce: enc.nonce })
                });
                if (!res.ok) throw new Error('Server returned ' + res.status);
                if (saveBackupStatus) { saveBackupStatus.textContent = '✅ Backup saved! (' + Object.keys(bundle).length + ' keys encrypted)'; saveBackupStatus.style.color = '#43b581'; }
                // Refresh the status indicator
                fetchBackupStatus();
            } catch (e) {
                if (saveBackupStatus) { saveBackupStatus.textContent = '❌ ' + (e.message || 'Save failed'); saveBackupStatus.style.color = 'var(--danger)'; }
            } finally {
                saveBackupNowBtn.disabled = false;
                saveBackupNowBtn.innerHTML = '&#128190; Save Backup Now';
            }
        });
    }

    // --- Restore from Server Backup (Settings → Security) ---
    var restoreBackupBtn = document.getElementById('restore-backup-btn');
    var restoreBackupSection = document.getElementById('restore-backup-section');
    var restoreBackupConfirmBtn = document.getElementById('restore-backup-confirm-btn');
    var restoreBackupCancelBtn = document.getElementById('restore-backup-cancel-btn');
    var restoreBackupStatus = document.getElementById('restore-backup-status');
    var restoreBackupPassword = document.getElementById('restore-backup-password');
    var restoreBackupToggle = document.getElementById('toggle-restore-backup-password');

    if (restoreBackupToggle && restoreBackupPassword) {
        restoreBackupToggle.addEventListener('click', function () {
            var visible = restoreBackupPassword.type === 'text';
            restoreBackupPassword.type = visible ? 'password' : 'text';
            restoreBackupToggle.innerHTML = visible ? '&#128065;' : '&#128064;';
            restoreBackupToggle.classList.toggle('active', !visible);
        });
    }

    if (restoreBackupBtn) {
        restoreBackupBtn.addEventListener('click', function () {
            var open = restoreBackupSection.style.display !== 'block';
            restoreBackupSection.style.display = open ? 'block' : 'none';
            if (open) {
                if (restoreBackupPassword) { restoreBackupPassword.type = 'password'; restoreBackupPassword.value = ''; restoreBackupPassword.focus(); }
                if (restoreBackupStatus) { restoreBackupStatus.textContent = ''; }
            }
        });
    }

    if (restoreBackupCancelBtn) {
        restoreBackupCancelBtn.addEventListener('click', function () {
            restoreBackupSection.style.display = 'none';
            if (restoreBackupStatus) restoreBackupStatus.textContent = '';
        });
    }

    if (restoreBackupConfirmBtn) {
        restoreBackupConfirmBtn.addEventListener('click', async function () {
            var pw = restoreBackupPassword ? restoreBackupPassword.value.trim() : '';
            if (!pw) {
                if (restoreBackupStatus) { restoreBackupStatus.textContent = '❌ Please enter your password.'; restoreBackupStatus.style.color = 'var(--danger)'; }
                return;
            }
            restoreBackupConfirmBtn.disabled = true;
            restoreBackupConfirmBtn.innerHTML = '⏳ Restoring...';
            try {
                // Ensure encrypted password exists for _secReKey
                if (!localStorage.getItem('e2e_encrypted_password')) {
                    storeEncryptedPassword(pw);
                }
                if (restoreBackupStatus) { restoreBackupStatus.textContent = '⏳ Fetching key backup from server...'; restoreBackupStatus.style.color = 'var(--text-muted)'; }
                var blobRes = await authFetch('/api/key-blob');
                if (!blobRes.ok) {
                    var errData = null;
                    try { errData = await blobRes.json(); } catch (_) {}
                    throw new Error((errData && errData.error) || 'Failed to fetch key backup');
                }
                var blobData = await blobRes.json();
                if (!blobData.encrypted_blob || !blobData.salt || !blobData.nonce) {
                    throw new Error('No key backup found on server. Keys are saved automatically at login and registration.');
                }
                if (restoreBackupStatus) restoreBackupStatus.textContent = '⏳ Decrypting key backup...';
                var bundle = E2ECrypto.decryptKeyBundle(blobData.encrypted_blob, pw, blobData.salt, blobData.nonce);
                if (!bundle) throw new Error('Wrong password or corrupted backup.');
                E2ECrypto.restoreKeyBundle(bundle);
                // Re-key secure-storage to use the password-derived key
                if (window._secReKey) {
                    try { window._secReKey(); } catch (_) {}
                }
                storeEncryptedPassword(pw);
                // Also restore friend code if present
                if (bundle['e2e_friend_code']) {
                    myFriendCode = bundle['e2e_friend_code'];
                }
                // Save updated blob back so newly joined servers are included
                saveKeyBlobToServer();
                if (restoreBackupStatus) { restoreBackupStatus.textContent = '✅ Keys restored successfully! All encryption keys, media caches, and friend code have been recovered.'; restoreBackupStatus.style.color = '#43b581'; }
                // Clear password field
                if (restoreBackupPassword) restoreBackupPassword.value = '';
            } catch (e) {
                if (restoreBackupStatus) { restoreBackupStatus.textContent = '❌ ' + (e.message || 'Recovery failed'); restoreBackupStatus.style.color = 'var(--danger)'; }
            } finally {
                restoreBackupConfirmBtn.disabled = false;
                restoreBackupConfirmBtn.innerHTML = '&#128260; Restore';
            }
        });
    }

    // --- Two-Factor Authentication (2FA) ---
    var twofaEnrollModal = document.getElementById('twofa-enroll-modal');
    var twofaDisableModal = document.getElementById('twofa-disable-modal');
    var enable2faBtn = document.getElementById('enable-2fa-btn');
    var disable2faBtn = document.getElementById('disable-2fa-btn');
    var _twofaEnroll = null; // { secret_base32, otpauth_url, recovery_codes, password }

    function show2FaModal(id) {
        var el = document.getElementById(id);
        if (el) {
            // 2FA flows are security-sensitive: the password field must always
            // start hidden — never carry over a previous show/hide state.
            if (id === 'twofa-enroll-modal') {
                var pwInput = document.getElementById('twofa-password');
                if (pwInput) { pwInput.type = 'password'; pwInput.value = ''; }
                var tgl = document.getElementById('toggle-twofa-password');
                if (tgl) { tgl.innerHTML = '&#128065;'; tgl.classList.remove('active'); }
            }
            el.style.display = 'flex';
        }
    }
    function hide2FaModal(id) {
        var el = document.getElementById(id);
        if (el) el.style.display = 'none';
    }

    async function load2FaStatus() {
        try {
            var res = await authFetch('/api/2fa/status');
            var data = await res.json();
            var line = document.getElementById('twofa-status-line');
            var on = !!(data && data.enabled);
            if (line) line.textContent = 'Two-factor authentication: ' + (on ? 'ON' : 'OFF');
            if (enable2faBtn) enable2faBtn.style.display = on ? 'none' : '';
            if (disable2faBtn) disable2faBtn.style.display = on ? '' : 'none';
        } catch (_) {}
    }

    // 2FA flows are security-sensitive: these modals are deliberately NOT
    // dismissible by clicking the backdrop or pressing Escape — the only way
    // out is the explicit Cancel button (or completing the flow successfully).

    if (enable2faBtn) {
        enable2faBtn.addEventListener('click', function () {
            _twofaEnroll = null;
            document.getElementById('twofa-step-password').style.display = 'block';
            document.getElementById('twofa-step-qr').style.display = 'none';
            document.getElementById('twofa-password-error').style.display = 'none';
            show2FaModal('twofa-enroll-modal');
        });
    }
    var twofaToggleBtn = document.getElementById('toggle-twofa-password');
    if (twofaToggleBtn) {
        twofaToggleBtn.addEventListener('click', function () {
            var inp = document.getElementById('twofa-password');
            var visible = inp.type === 'text';
            inp.type = visible ? 'password' : 'text';
            twofaToggleBtn.innerHTML = visible ? '&#128065;' : '&#128064;';
            twofaToggleBtn.classList.toggle('active', !visible);
        });
    }
    var twofaEnrollCancel = document.getElementById('twofa-enroll-cancel');
    if (twofaEnrollCancel) twofaEnrollCancel.addEventListener('click', function () { hide2FaModal('twofa-enroll-modal'); });

    // Begin enrollment: confirm password → server mints secret + recovery codes.
    var twofaStartBtn = document.getElementById('twofa-start-btn');
    if (twofaStartBtn) {
        twofaStartBtn.addEventListener('click', async function () {
            var password = document.getElementById('twofa-password').value;
            var errEl = document.getElementById('twofa-password-error');
            if (!password) { errEl.textContent = 'Enter your password'; errEl.style.display = 'block'; return; }
            var btn = this;
            btn.disabled = true;
            try {
                var sendPassword;
                try { sendPassword = await computeHashedPasswordGlobal(password); }
                catch (_) { sendPassword = password; }
                var res = await authFetch('/api/2fa/enroll', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ password: sendPassword })
                });
                var data = await res.json();
                if (!res.ok) {
                    errEl.textContent = data.error || 'Enrollment failed';
                    errEl.style.display = 'block';
                    btn.disabled = false;
                    return;
                }
                _twofaEnroll = { secret_base32: data.secret_base32, otpauth_url: data.otpauth_url, recovery_codes: data.recovery_codes, password: sendPassword };
                var qrEl = document.getElementById('twofa-qr');
                qrEl.innerHTML = '';
                try {
                    var qr = qrcode(0, 'M');
                    qr.addData(data.otpauth_url);
                    qr.make();
                    qrEl.innerHTML = qr.createImgTag(4, 8);
                } catch (qrErr) {
                    qrEl.textContent = 'QR unavailable — enter the secret manually below.';
                }
                document.getElementById('twofa-secret-text').textContent = 'Secret: ' + data.secret_base32;
                var codesEl = document.getElementById('twofa-recovery-codes');
                codesEl.innerHTML = '';
                data.recovery_codes.forEach(function (c) {
                    var span = document.createElement('span');
                    span.textContent = c;
                    codesEl.appendChild(span);
                });
                document.getElementById('twofa-step-password').style.display = 'none';
                document.getElementById('twofa-step-qr').style.display = 'block';
                document.getElementById('twofa-verify-code').value = '';
                document.getElementById('twofa-verify-error').style.display = 'none';
            } catch (e) {
                errEl.textContent = 'Server is not running';
                errEl.style.display = 'block';
            }
            btn.disabled = false;
        });
    }

    var twofaCopyBtn = document.getElementById('twofa-copy-codes');
    if (twofaCopyBtn) {
        twofaCopyBtn.addEventListener('click', function () {
            if (!_twofaEnroll || !_twofaEnroll.recovery_codes) return;
            var text = _twofaEnroll.recovery_codes.join('\n');
            var ta = document.createElement('textarea');
            ta.value = text;
            document.body.appendChild(ta);
            ta.select();
            try { document.execCommand('copy'); } catch (_) {}
            document.body.removeChild(ta);
            var st = document.getElementById('twofa-copy-status');
            if (st) { st.textContent = 'Copied!'; setTimeout(function () { st.textContent = ''; }, 2000); }
        });
    }

    // Download the recovery codes as a text file (one-time codes — save them
