    // ─── Scheduled Messages ──────────────────────────────────────────
    // Store scheduled messages locally (encrypted via the key blob). The
    // scheduler checks every second and sends any that are due.
    var _scheduledMessages = [];

    function loadScheduledMessages() {
        try {
            var raw = localStorage.getItem('scheduled_messages');
            if (raw) _scheduledMessages = JSON.parse(raw);
        } catch (_) { _scheduledMessages = []; }
    }

    function saveScheduledMessages() {
        try { localStorage.setItem('scheduled_messages', JSON.stringify(_scheduledMessages)); } catch (_) {}
    }

    function openScheduleModal() {
        var modal = document.getElementById('schedule-msg-modal');
        if (!modal) return;
        modal.style.display = 'flex';
        // Default to 1 hour from now
        var now = new Date();
        now.setHours(now.getHours() + 1);
        document.getElementById('schedule-msg-date').value = now.toISOString().slice(0, 10);
        document.getElementById('schedule-msg-time').value = now.toTimeString().slice(0, 5);
        document.getElementById('schedule-msg-text').value = '';
        document.getElementById('schedule-msg-error').style.display = 'none';
        renderScheduledList();
    }

    function closeScheduleModal() {
        var modal = document.getElementById('schedule-msg-modal');
        if (modal) modal.style.display = 'none';
    }

        function renderScheduledList() {
        var list = document.getElementById('schedule-msg-list');
        if (!list) return;
        var html = '';
        _scheduledMessages.forEach(function (msg, i) {
            var d = new Date(msg.sendAt);
            var ts = d.toLocaleString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
            var ch = msg.channelId ? 'Channel' : (msg.dmOtherUsername ? 'DM \u2192 ' + msg.dmOtherUsername : 'DM');
            html += '<div class="sch-item">' +
                '<div class="sch-info"><span class="sch-time">' + ts + '</span> <span class="sch-dest">' + ch + '</span><div class="sch-preview">' + (msg.text || '').substring(0, 50) + '</div></div>' +
                '<button class="sch-cancel-btn" data-sch-action="cancel" data-sch-idx="' + i + '" title="Cancel">\u2715</button>' +
                '</div>';
        });
        if (!_scheduledMessages.length) html = '<div class="sch-empty">No scheduled messages</div>';
        list.innerHTML = html;
        renderSecurityScheduledList();
    }

    // Event-delegated handlers for schedule list buttons (modal + user settings)
    (function () {
        var modalList = document.getElementById('schedule-msg-list');
        var userList = document.getElementById('user-scheduled-list');

        function handleSchClick(e) {
            var btn = e.target.closest('[data-sch-action]');
            if (!btn) return;
            var idx = parseInt(btn.getAttribute('data-sch-idx'), 10);
            if (isNaN(idx)) return;
            var action = btn.getAttribute('data-sch-action');
            if (action === 'cancel') {
                _scheduledMessages.splice(idx, 1);
                saveScheduledMessages();
                renderScheduledList();
                renderSecurityScheduledList();
            } else if (action === 'delay') {
                var mins = parseInt(btn.getAttribute('data-sch-mins'), 10) || 5;
                var msg = _scheduledMessages[idx];
                if (msg) {
                    msg.sendAt = new Date(new Date(msg.sendAt).getTime() + mins * 60000).toISOString();
                    saveScheduledMessages();
                    renderScheduledList();
                    renderSecurityScheduledList();
                }
            }
        }
        if (modalList) modalList.addEventListener('click', handleSchClick);
        if (userList) userList.addEventListener('click', handleSchClick);
    })();


    function renderSecurityScheduledList() {
        var list = document.getElementById('user-scheduled-list');
        if (!list) return;
        // Reload from localStorage in case it was modified externally
        loadScheduledMessages();
        if (!_scheduledMessages.length) {
            list.innerHTML = '<div class="sch-empty-state">\u23F0 No scheduled messages</div>';
            return;
        }
        var html = '';
        _scheduledMessages.forEach(function (msg, i) {
            var d = new Date(msg.sendAt);
            var now = Date.now();
            var diff = d.getTime() - now;
            var mins = Math.max(0, Math.round(diff / 60000));
            var timeLabel = mins < 60 ? mins + 'm' : Math.floor(mins / 60) + 'h ' + (mins % 60) + 'm';
            var ts = d.toLocaleString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
            var ch = msg.channelId ? '\u{1F4AC} Channel' : (msg.dmOtherUsername ? '\u{1F4AC} DM \u2192 ' + msg.dmOtherUsername : '\u{1F4AC} DM');
            var urgencyClass = diff < 300000 ? ' sch-item-urgent' : diff < 3600000 ? ' sch-item-soon' : '';
            html += '<div class="sch-item' + urgencyClass + '">' +
                '<div class="sch-item-icon">\u{1F4DD}</div>' +
                '<div class="sch-info">' +
                    '<div class="sch-top-row"><span class="sch-time">' + ts + '</span><span class="sch-countdown">in ' + timeLabel + '</span></div>' +
                    '<div class="sch-dest">' + ch + '</div>' +
                    '<div class="sch-preview">\u201C' + (msg.text || '').substring(0, 60) + '\u201D</div>' +
                '</div>' +
                '<div class="sch-actions">' +
                    '<button class="sch-action-btn" data-sch-action="delay" data-sch-idx="' + i + '" data-sch-mins="5" title="Delay 5 min">\u23F0 +5m</button>' +
                    '<button class="sch-action-btn" data-sch-action="delay" data-sch-idx="' + i + '" data-sch-mins="30" title="Delay 30 min">\u23F0 +30m</button>' +
                    '<button class="sch-action-btn" data-sch-action="delay" data-sch-idx="' + i + '" data-sch-mins="60" title="Delay 1 hour">\u23F0 +1h</button>' +
                    '<button class="sch-action-btn sch-action-cancel" data-sch-action="cancel" data-sch-idx="' + i + '" title="Cancel">\u2715</button>' +
                '</div>' +
                '</div>';
        });
        list.innerHTML = html;
    }

    function confirmScheduleMsg() {
        var text = document.getElementById('schedule-msg-text').value.trim();
        var dateVal = document.getElementById('schedule-msg-date').value;
        var timeVal = document.getElementById('schedule-msg-time').value;
        var errEl = document.getElementById('schedule-msg-error');
        if (!text) { errEl.textContent = 'Message cannot be empty'; errEl.style.display = ''; return; }
        if (!dateVal || !timeVal) { errEl.textContent = 'Pick a date and time'; errEl.style.display = ''; return; }
        var sendAt = new Date(dateVal + 'T' + timeVal + ':00');
        if (isNaN(sendAt.getTime()) || sendAt.getTime() <= Date.now()) {
            errEl.textContent = 'Schedule time must be in the future'; errEl.style.display = ''; return;
        }
        _scheduledMessages.push({
            text: text,
            sendAt: sendAt.toISOString(),
            channelId: currentChannelId || null,
            serverId: currentServerId || null,
            dmChannelId: currentDmChannelId || null,
            dmOtherUserId: currentDmOtherUser ? currentDmOtherUser.id : null,
            dmOtherUsername: currentDmOtherUser ? currentDmOtherUser.username : null,
            dmOtherUser: currentDmOtherUser || null,
            created: Date.now()
        });
        saveScheduledMessages();
        closeScheduleModal();
    }

    // Wire schedule modal buttons
    var _scheduleAttachHandler = null;
    document.getElementById('schedule-msg-confirm').addEventListener('click', confirmScheduleMsg);
    document.getElementById('schedule-msg-cancel').addEventListener('click', closeScheduleModal);
    loadScheduledMessages();

        // Scheduler tick: check every second and send any due messages
    setInterval(function () {
        var now = Date.now();
        for (var i = _scheduledMessages.length - 1; i >= 0; i--) {
            var msg = _scheduledMessages[i];
            if (new Date(msg.sendAt).getTime() <= now) {
                (function (_msg) {
                    try {
                        if (!document.getElementById('message-input') || !_msg.text || !ws || ws.readyState !== WebSocket.OPEN) return;
                        if (_msg.channelId && _msg.serverId) {
                            var encKey = E2ECrypto.getServerKey(_msg.serverId);
                            if (!encKey) return;
                            var encrypted = E2ECrypto.encryptMessage(_msg.text, encKey);
                            var payload = {
                                type: 'message_send',
                                channel_id: _msg.channelId,
                                encrypted_content: encrypted.ciphertext,
                                nonce: encrypted.nonce,
                                message_nonce: encrypted.messageNonce || null,
                            };
                            try {
                                var _toks = E2ECrypto.searchTokensForText(extractSearchableText(_msg.text), E2ECrypto.getAllServerKeys(_msg.serverId) || []);
                                if (_toks.length) payload.search_tokens = _toks;
                            } catch (_) {}
                            // Attach encrypted profile snapshot so PFP/display name render without reload
                            try {
                                if (myProfile && encKey) {
                                    var _snap = {
                                        display_name: myProfile.display_name || (user && user.username) || '',
                                        username_color: myProfile.username_color || (user && user.username_color) || null,
                                        username_border_color: myProfile.username_border_color || null,
                                        nickname: myProfile.nickname || null,
                                        description: myProfile.description || null,
                                        profile_background_color: myProfile.profile_background_color || null,
                                        profile_picture_file_id: myProfile.profile_picture_file_id || null,
                                        profile_picture_file_key: null
                                    };
                                    if (myProfile.profile_picture_file_id && myProfile.profile_picture_file_key) {
                                        var _identity = E2ECrypto.getIdentityKeyPair();
                                        if (_identity) {
                                            var _rawPicKey = myProfile.profile_picture_file_key;
                                            if (_rawPicKey.indexOf(':') > 0) {
                                                var _dk = E2ECrypto.decodeEncryptedFileKey(_rawPicKey, _identity.privateKey);
                                                if (_dk) _rawPicKey = _dk;
                                            }
                                            _snap.profile_picture_file_key = _rawPicKey;
                                        }
                                    }
                                    var _pdKey = profileKeyCache[user.id + ':profile_data_key'];
                                    if (_pdKey) _snap.profile_data_key = _pdKey;
                                    var _snapJson = JSON.stringify(_snap);
                                    var _encSnap = E2ECrypto.encryptMessage(_snapJson, encKey);
                                    if (_encSnap) {
                                        payload.encrypted_profile_snapshot = _encSnap.ciphertext;
                                        payload.profile_snapshot_nonce = _encSnap.nonce;
                                    }
                                }
                            } catch (_) {}
                            // Encrypted sender username
                            try {
                                if (encKey && user) {
                                    var _encU = E2ECrypto.encryptSenderUsername(user.username, encKey);
                                    if (_encU) {
                                        payload.encrypted_sender_username = _encU.ciphertext;
                                        payload.sender_username_nonce = _encU.nonce;
                                    }
                                }
                            } catch (_) {}
                            // Inject profile snapshot into local cache so sender sees PFP/name immediately
                            try {
                                if (myProfile && user) {
                                    if (!userDisplayNameCache[user.id]) userDisplayNameCache[user.id] = {};
                                    userDisplayNameCache[user.id].display_name = myProfile.display_name || user.username;
                                    if (myProfile.username_color) userDisplayNameCache[user.id].username_color = myProfile.username_color;
                                    if (myProfile.profile_picture_file_id) userDisplayNameCache[user.id].profile_picture_file_id = myProfile.profile_picture_file_id;
                                    if (myProfile.profile_picture_file_key) userDisplayNameCache[user.id].profile_picture_file_key = myProfile.profile_picture_file_key;
                                    scheduleUserDisplayNameSave();
                                }
                            } catch (_) {}
                            ws.send(JSON.stringify(payload));
                            var idx = _scheduledMessages.indexOf(_msg);
                            if (idx !== -1) _scheduledMessages.splice(idx, 1);
                            saveScheduledMessages();
                        } else if (_msg.dmChannelId && _msg.dmOtherUserId) {
                            var kp = E2ECrypto.getIdentityKeyPair();
                            if (!kp) return;
                            fetch('/api/identity/' + _msg.dmOtherUserId).then(function (r) { return r.json(); }).then(function (data) {
                                var otherPub = new Uint8Array(E2ECrypto.base64ToArrayBuffer(data.identity_public_key));
                                var encrypted = E2ECrypto.encryptDm(_msg.text, _msg.dmChannelId, kp.privateKey, otherPub);
                                var payload = {
                                    type: 'dm_send',
                                    dm_channel_id: _msg.dmChannelId,
                                    encrypted_content: encrypted.ciphertext,
                                    nonce: encrypted.nonce,
                                    message_nonce: encrypted.messageNonce || null,
                                };
                                try {
                                    var _dmk = E2ECrypto.getDmKey(_msg.dmChannelId, kp.privateKey, otherPub);
                                    if (_dmk) {
                                        var _dmtoks = E2ECrypto.searchTokensForText(extractSearchableText(_msg.text), [_dmk]);
                                        if (_dmtoks.length) payload.search_tokens = _dmtoks;
                                    }
                                } catch (_) {}
                                ws.send(JSON.stringify(payload));
                                var idx = _scheduledMessages.indexOf(_msg);
                                if (idx !== -1) _scheduledMessages.splice(idx, 1);
                                saveScheduledMessages();
                            }).catch(function () {});
                        }
                    } catch (e) {
                        console.error('[Scheduler] send failed:', e);
                    }
                })(msg);
            }
        }
    }, 1000);

    // Typing indicator: send a throttled `typing` WS message while typing,
    // and keep refreshing it (Discord-style) so the other side's 4s auto-hide
    // never fires mid-typing. Cleared automatically on send (input clears).
    document.getElementById('message-input').addEventListener('input', function () {
        sendTypingSignal();
        if (_typingRefreshTimer) clearTimeout(_typingRefreshTimer);
        _typingRefreshTimer = setTimeout(sendTypingSignal, 2000);
    });

