        attachPopup.addEventListener('click', function (e) {
            var item = e.target.closest('.attach-popup-item');
            if (!item) return;
            var action = item.dataset.action;
            closeAttachPopup();
            if (action === 'upload') {
                document.getElementById('file-input').click();
            } else if (action === 'photo') {
                openCameraCapture();
            } else if (action === 'record-video') {
                startVideoRecording();
            } else if (action === 'poll') {
                if (window.openCreatePollModal) window.openCreatePollModal();
            } else if (action === 'schedule') {
                openScheduleModal();
            } else if (action === 'vault-send') {
                openVaultSendPicker();
            }
            // 'record-audio' is handled by the record-audio click handler below
        });
